/**
 * 负责编排单个原生 SDK 回合；输入为原引擎请求、提示会话与模型客户端，输出为候选工具、重试／回退和玩家记录。
 * 本 owner 持有控制器、截止计时器与待结束任务；最早期限覆盖排队和各次尝试，请求绑定仍由各机制检查。
 * 并发租约只在本回合收尾时释放；每轮取消不可逆，关闭单向封住本 owner，任务兑现不等于领域提交。
 * 取消／关闭仅收走本 provider 资源，不代替规则预检或领域 commit，不扩大 fallback 的原预算。
 */
import { inheritRequestAlias } from "../../../core/domain/request_delivery";
import { text } from "@ai-werewolf-arena/game-text";
import type { ErrorDiagnostic } from "@ai-werewolf-arena/replay-contract";
import { describeError, formatErrorDiagnostic } from "../../../utils/error_diagnostic";
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import { ActionRequest, ToolCall } from "../../../core/domain";
import { World } from "../../../core/domain/world";
import {
  FallbackActionPolicy,
  FallbackDeadlineElapsed,
  FallbackReason,
} from "./fallback_action_policy";
import { LlmObserver } from "../player/player_observer";
import { BuiltPlayerPrompt, PlayerRoundOutcome, PlayerRetryTraceEntry } from "../player/contracts";
import { ChatMessage, ChatModelClient } from "../../integrations/llm/transport";
import { PlayerPromptSession } from "./player_prompt_session";
import { PlayerRoundRecorder } from "../../../app/player-round-recorder";
import { buildConstraintRetryPrompt } from "../player/prompt_templates";
import { ScopedRequestScheduler } from "../../runtime/request_scheduler";
import { SdkGameToolLoop } from "./sdk_game_tool_loop";
import { allowsActionFallback, resolveTurnConstraints } from "../../../game/gateway/turn-constraints";

interface LlmTurnOrchestratorOptions {
  world: World;
  defaultClient: ChatModelClient;
  clientResolver?: (request: ActionRequest, role?: RoleComponent) => ChatModelClient;
  timeoutMs: number;
  promptSession: PlayerPromptSession;
  scheduler: ScopedRequestScheduler;
  sdkToolLoop: SdkGameToolLoop;
  fallbackPolicy: FallbackActionPolicy;
  recorder: PlayerRoundRecorder;
  observer: LlmObserver;
}

interface NativeAttempt {
  action: ToolCall | null;
  failed: boolean;
  deadlineExceeded?: boolean;
  diagnostic?: ErrorDiagnostic;
  assistantText?: string;
  refusalReason?: string;
}

/** 以原尝试顺序编排原生工具回合，已付／已记录前缀不由本服务回滚。 */
export class LlmTurnOrchestrator {
  constructor(private readonly options: LlmTurnOrchestratorOptions) {}

  private readonly controllers = new Set<AbortController>();
  private readonly pending = new Set<Promise<ToolCall | null>>();
  private readonly closeController = new AbortController();
  private closed = false;

  get runtimeState() {
    return {
      closed: this.closed,
      turns: this.pending.size,
      scheduler: this.options.scheduler.snapshot,
    };
  }

  run(request: ActionRequest): Promise<ToolCall | null> {
    if (this.closed) return Promise.reject(new DOMException("llm_provider_closed", "AbortError"));
    const startedAt = Date.now();
    // 只取引擎原期限与本次启动预算的较早者；排队和重试共用它，不为每次模型调用重新计时。
    const bounded = {
      ...request,
      deadlineAtMs: Math.min(request.deadlineAtMs ?? Infinity, startedAt + this.options.timeoutMs),
    };
    // bounded 是新请求对象：按原机制路线继承绑定，不凭 actorId 或浅复制字段重建领域许可。
    inheritRequestAlias(request, bounded);
    const controller = new AbortController();
    this.controllers.add(controller);
    const timer = setTimeout(
      () => controller.abort(new Error("request_deadline_elapsed")),
      Math.max(0, bounded.deadlineAtMs - Date.now()),
    );
    let resolve!: (action: ToolCall | null) => void, reject!: (error: unknown) => void;
    const task = new Promise<ToolCall | null>((done, fail) => {
      resolve = done;
      reject = fail;
    });
    // 在 runTurn 的提示／客户端回调开始前登记任务，让同步重入的 close 也能看到这次回合。
    this.pending.add(task);
    void this.runTurn(bounded, controller.signal, startedAt).then(resolve, reject);
    const cleanup = () => {
      clearTimeout(timer);
      this.controllers.delete(controller);
      this.pending.delete(task);
    };
    return task.then(
      (action) => {
        cleanup();
        if (this.closed) return this.closedResult(request);
        if (
          bounded.context.action_failure_policy === "error" &&
          (controller.signal.aborted || bounded.deadlineAtMs <= Date.now())
        )
          throw new Error("action_turn_failed");
        return action;
      },
      (error) => {
        cleanup();
        throw error;
      },
    );
  }

  async close(): Promise<void> {
    this.closed = true;
    this.closeController.abort(new DOMException("llm_provider_closed", "AbortError"));
    // 队列先关闭，再中止运行任务；控制器保留首次中止原因，已授予租约仍走各回合 finally。
    this.options.scheduler.close(this.closeController.signal.reason);
    for (const controller of this.controllers) controller.abort(this.closeController.signal.reason);
    const settled = await Promise.allSettled([...this.pending]);
    // 已知关闭原因按同一对象识别，其它拒绝仍汇总；allSettled 不把传输失败抹成关闭成功。
    const failures = settled.flatMap((result) =>
      result.status === "rejected" && result.reason !== this.closeController.signal.reason
        ? [result.reason]
        : [],
    );
    if (failures.length) throw new AggregateError(failures, "llm_turns_failed_during_close");
  }

  private async runTurn(
    request: ActionRequest,
    signal: AbortSignal,
    startedAt: number,
  ): Promise<ToolCall | null> {
    const role = this.options.world.getComponent(request.actorId, COMPONENT.Role);
    const client = this.options.clientResolver?.(request, role) ?? this.options.defaultClient;
    const prompt = this.options.promptSession.build(request);
    this.options.observer.trace(
      `context_window player=${request.actorId} phase=${request.phase} start=${prompt.contextWindowStart} end=${prompt.contextWindowEnd} total=${prompt.contextWindowTotal}`,
    );
    let release: (() => void) | undefined;
    try {
      release = await this.options.scheduler.acquire(request, role, signal);
      if (this.closed) return this.closedResult(request);
      if (signal.aborted || this.effectiveTimeout(request.deadlineAtMs) <= 0) {
        return this.finishWithFallback(request, prompt, "deadline_skip");
      }
      this.options.observer.trace(
        `request_start player=${request.actorId} phase=${request.phase} tools=${request.allowedTools.join(",")} timeout_ms=${this.effectiveTimeout(request.deadlineAtMs)}`,
      );
      this.options.observer.prompt(prompt.messages, request);
      const action = await this.runNative(client, request, prompt, startedAt, signal);
      if (
        !this.closed &&
        request.context.action_failure_policy === "error" &&
        (signal.aborted || this.effectiveTimeout(request.deadlineAtMs) <= 0)
      ) {
        return this.finishWithFallback(request, prompt, "deadline_skip", {
          retryTrace: [
            {
              attempt: 0,
              status: "request_error",
              reason: "request_timeout",
              diagnostic: { code: "request_timeout" },
            },
          ],
        });
      }
      return this.closed ? this.closedResult(request) : action;
    } catch (error) {
      const diagnostic = describeError(error);
      if (this.closed && (error === this.closeController.signal.reason || error === signal.reason))
        return this.closedResult(request);
      // 原生传输失败已由 runNative 处理；回退或记录失败只传播一次，不能再次调用回退。
      if (release) throw error;
      this.options.observer.trace(
        `${diagnostic.code === "request_timeout" ? "request_timeout" : "request_transport_fail"} player=${request.actorId} phase=${request.phase} elapsed_ms=${Date.now() - startedAt} err=${formatErrorDiagnostic(error, this.options.observer.locale)}`,
      );
      return this.finishWithFallback(
        request,
        prompt,
        diagnostic.code === "request_timeout" ? "deadline_skip" : "runtime_error",
      );
    } finally {
      // 无论成功、记录／回退失败还是取消，都由取得租约的本回合释放；不在模型刚选出动作时提前放槽。
      release?.();
    }
  }

  private async runNative(
    client: ChatModelClient,
    request: ActionRequest,
    prompt: BuiltPlayerPrompt,
    startedAt: number,
    signal: AbortSignal,
  ): Promise<ToolCall | null> {
    const retryTrace: PlayerRetryTraceEntry[] = [];
    // 每次尝试使用同一 bounded 请求的剩余期限；迟到结果在原检查点复核关闭／错误策略。
    const attempt = async (messages: ChatMessage[]): Promise<NativeAttempt> => {
      const timeoutMs = this.effectiveTimeout(request.deadlineAtMs);
      if (signal.aborted || timeoutMs <= 0) {
        return {
          action: null,
          failed: false,
          deadlineExceeded: true,
          diagnostic: { code: "request_timeout" },
        };
      }
      try {
        const result = await this.options.sdkToolLoop.run(
          client,
          request,
          messages,
          timeoutMs,
          prompt.turnId,
          signal,
        );
        if (
          request.context.action_failure_policy === "error" &&
          (signal.aborted || this.effectiveTimeout(request.deadlineAtMs) <= 0)
        ) {
          return {
            action: null,
            failed: false,
            deadlineExceeded: true,
            diagnostic: { code: "request_timeout" },
          };
        }
        return {
          action: result.action,
          failed: result.failureCode !== undefined,
          refusalReason: result.failureCode,
          assistantText: result.thinkingText,
        };
      } catch (error) {
        const diagnostic = describeError(error);
        this.options.observer.trace(
          `request_sdk_attempt_fail player=${request.actorId} phase=${request.phase} err=${formatErrorDiagnostic(error, this.options.observer.locale)}`,
        );
        return { action: null, failed: true, diagnostic };
      }
    };

    const first = await attempt(prompt.messages);
    if (this.closed) return this.closedResult(request);
    if (first.deadlineExceeded)
      return this.finishWithFallback(request, prompt, "deadline_skip", {
        ...(request.context.action_failure_policy === "error"
          ? {
              retryTrace: [
                {
                  attempt: 0,
                  status: "request_error" as const,
                  reason: "request_timeout",
                  diagnostic: first.diagnostic ?? { code: "request_timeout" as const },
                },
              ],
            }
          : {}),
      });
    if (first.failed) {
      retryTrace.push({
        attempt: 0,
        status: first.refusalReason ? "no_valid_action" : "request_error",
        reason: first.refusalReason ?? first.diagnostic?.code,
        diagnostic: first.diagnostic,
        assistantText: first.assistantText,
      });
      return this.finishWithFallback(
        request,
        prompt,
        first.refusalReason ? "model_declined_required_action" : "runtime_error",
        {
          thinkingText: first.assistantText,
          retryTrace,
        },
      );
    }
    if (first.action)
      return this.finishWithAction(request, prompt, first.action, startedAt, {
        thinkingText: first.assistantText,
      });
    if (!this.requiresAction(request)) {
      this.options.observer.trace(
        `request_none player=${request.actorId} phase=${request.phase} elapsed_ms=${Date.now() - startedAt}`,
      );
      this.options.recorder.record(request, prompt, {
        actionMode: "none",
        toolCalls: [],
        thinkingText: first.assistantText,
      });
      return null;
    }

    retryTrace.push({
      attempt: 0,
      status: "no_valid_action",
      reason: "turn_constraints_no_valid_action",
      assistantText: first.assistantText,
    });
    let messages = [...prompt.messages];
    for (let attemptNumber = 1; attemptNumber <= 3; attemptNumber++) {
      const retryPrompt = buildConstraintRetryPrompt(attemptNumber, 3, this.options.world.locale);
      messages = [...messages, { role: "user", content: retryPrompt }];
      console.log(
        `[LLM_RETRY] player=${request.actorId} phase=${request.phase} attempt=${attemptNumber}/3 reason=turn_constraints_no_valid_action · ${text(this.options.observer.locale, "runtime.retry")}`,
      );
      const trace: PlayerRetryTraceEntry = {
        attempt: attemptNumber,
        status: "no_valid_action",
        reason: "turn_constraints_no_valid_action",
        retryPrompt,
      };
      retryTrace.push(trace);
      this.options.observer.prompt(messages, request);
      const result = await attempt(messages);
      if (this.closed) return this.closedResult(request);
      trace.assistantText = result.assistantText;
      if (result.deadlineExceeded) {
        trace.reason = result.diagnostic?.code;
        trace.diagnostic = result.diagnostic;
        return this.finishWithFallback(request, prompt, "deadline_skip", {
          thinkingText: result.assistantText,
          retryTrace,
        });
      }
      if (result.failed) {
        trace.status = result.refusalReason ? "no_valid_action" : "request_error";
        trace.reason = result.refusalReason ?? result.diagnostic?.code;
        trace.diagnostic = result.diagnostic;
        return this.finishWithFallback(
          request,
          prompt,
          result.refusalReason ? "model_declined_required_action" : "runtime_error",
          {
            thinkingText: result.assistantText,
            retryTrace,
          },
        );
      }
      if (result.action) {
        return this.finishWithAction(request, prompt, result.action, startedAt, {
          thinkingText: result.assistantText,
          retryTrace,
          retryAttempt: attemptNumber,
        });
      }
    }
    return this.finishWithFallback(request, prompt, "model_declined_required_action", {
      thinkingText: retryTrace.at(-1)?.assistantText,
      retryTrace,
    });
  }

  private async finishWithAction(
    request: ActionRequest,
    prompt: BuiltPlayerPrompt,
    action: ToolCall,
    startedAt: number,
    extras: {
      thinkingText?: string;
      retryTrace?: PlayerRetryTraceEntry[];
      retryAttempt?: number;
    } = {},
  ): Promise<ToolCall | null> {
    if (this.closed) return this.closedResult(request);
    this.options.observer.trace(
      `${extras.retryAttempt ? "request_ok_retry" : "request_ok"} player=${request.actorId} phase=${request.phase}${extras.retryAttempt ? ` attempt=${extras.retryAttempt}/3` : ""} action=${action.name} args=${JSON.stringify((action as any).args ?? {})} elapsed_ms=${Date.now() - startedAt}`,
    );
    if (this.closed) return this.closedResult(request);
    this.options.recorder.record(request, prompt, {
      actionMode: "tool_call",
      toolCalls: this.toToolCalls(action),
      finalAction: action,
      thinkingText: extras.thinkingText,
      ...(extras.retryTrace?.length ? { retryTrace: [...extras.retryTrace] } : {}),
    });
    return this.closed ? this.closedResult(request) : action;
  }

  private async finishWithFallback(
    request: ActionRequest,
    prompt: BuiltPlayerPrompt,
    reason: FallbackReason,
    extras: Pick<PlayerRoundOutcome, "thinkingText" | "retryTrace"> = {},
  ): Promise<ToolCall | null> {
    if (this.closed) return this.closedResult(request);
    let action: ToolCall | null;
    try {
      action = await this.options.fallbackPolicy.resolve(
        request,
        reason,
        this.closeController.signal,
      );
    } catch (error) {
      if (error === this.closeController.signal.reason) return this.closedResult(request);
      if (!(error instanceof FallbackDeadlineElapsed)) throw error;
      action = null;
      reason = "deadline_skip";
    }
    if (this.closed) return this.closedResult(request);
    this.options.recorder.record(request, prompt, {
      actionMode: action ? "tool_call" : "none",
      toolCalls: this.toToolCalls(action),
      finalAction: action,
      ...extras,
      fallback: {
        used: allowsActionFallback(request),
        reason,
        ...(action ? { action: { name: action.name, args: (action as any).args ?? {} } } : {}),
      },
    });
    if (!this.closed && request.context.action_failure_policy === "error" && !action)
      throw new Error("action_turn_failed");
    return this.closed ? this.closedResult(request) : action;
  }

  private toToolCalls(action?: ToolCall | null) {
    return action
      ? [
          {
            name: action.name,
            args: ((action as any).args ?? {}) as Record<string, unknown>,
            accepted: true,
          },
        ]
      : [];
  }

  private requiresAction(request: ActionRequest): boolean {
    return resolveTurnConstraints(request).minValidActions > 0;
  }
  private closedResult(request: ActionRequest): null {
    if (request.context.action_failure_policy === "error") throw this.closeController.signal.reason;
    return null;
  }

  private effectiveTimeout(deadlineAtMs?: number): number {
    if (!deadlineAtMs) return this.options.timeoutMs;
    const remaining = deadlineAtMs - Date.now();
    return remaining <= 0 ? 0 : Math.max(1, Math.min(this.options.timeoutMs, remaining));
  }
}

/**
 * 负责将引擎请求适配为 ACP 会话和会话绑定的 MCP 行动。输入为 World、解析后的选项与请求；输出为已接受工具及回合记录。默认生产回退只把脱离玩家观察交给策略，显式特权驱动单列测试接口。原回合 owner 持有期限、取消和关闭；ACP 文本与 update 不提交游戏行动。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { inheritRequestAlias } from "../../../core/domain/request_delivery";
import { allowsActionFallback, resolveTurnConstraints } from "../../../game/gateway/turn-constraints";
import type { ErrorDiagnostic } from "@ai-werewolf-arena/replay-contract";
import { describeError, formatErrorDiagnostic } from "../../../utils/error_diagnostic";
import { text, type Locale } from "@ai-werewolf-arena/game-text";
import { RoleComponent } from "../../../core/domain/components/role";
import { ActionProvider, ActionRequest, ToolCall } from "../../../core/domain";
import { World } from "../../../core/domain/world";
import {
  getDefaultConfigRenderRegistry,
  getDefaultPhaseStageLocalizationRegistry,
  getDefaultRoleCatalog,
  getDefaultTargetHintRegistry,
  getDefaultToolSpecRegistry,
  type RoleCatalog,
} from "../../../game/mechanisms";
import { safeRecordLogicOp } from "../../../recording/session_recorder";
import {
  AcpSession,
  AcpSessionAuditTrace,
  AcpSessionFactory,
} from "../../integrations/acp/session";
import {
  awaitBeforeDeadline,
  awaitWithAbort,
  TurnDeadlineElapsed,
  settleWithin,
} from "../../runtime/turn_deadline";
import { AcpSessionPool } from "./session_pool";
import {
  AcpBugReport,
  AcpTurnRegistry,
  McpBridgeResult,
} from "../../integrations/acp/acp_turn_registry";
import {
  ObservationFallbackActionProvider,
  ObservationFallbackStrategy,
} from "../providers/observation-fallback";
import type { ObservedPlayerStrategy } from "../../../game/observation/player-observation";
import { AgentBugReportService } from "../reporting/bug_report_service";
import { encodePlayerVisibleEventBatch, parsePlayerVisibleEvents } from "../visible_event_protocol";
import { BuiltPlayerPrompt, PlayerRoundOutcome } from "../player/contracts";
import { PlayerPromptPolicy } from "../player/player_prompt_policy";
import { PlayerRoundRecorder } from "../../../app/player-round-recorder";
import { ScopedRequestScheduler } from "../../runtime/request_scheduler";
import { LlmObserver } from "../player/player_observer";

export interface AcpActionProviderOptions {
  /** 生产自定义选择只接收脱离的玩家观察，不获得原请求或 World。 */
  fallbackStrategy?: ObservedPlayerStrategy;
  /** 显式特权测试驱动；生产运行装配不注入，保留原请求身份和取消测试。 */
  privilegedFallbackProvider?: ActionProvider;
  sessionFactory?: AcpSessionFactory;
  sessionFactoryResolver?: (actorId: number) => AcpSessionFactory;
  boardConfig?: ReadonlyBoardConfig;
  personalityPromptResolver?: (request: ActionRequest, role?: RoleComponent) => string | undefined;
  turnTimeoutMs?: number;
  onBugReport?: (report: AcpBugReport) => void;
  maxConcurrentRequests?: number;
  trace?: boolean;
  displayLocale?: Locale;
  colorizeLogs?: boolean;
  printLlmIo?: boolean;
  printThinking?: boolean;
  roleCatalog?: RoleCatalog;
}

interface AcpTurnPromptBuild {
  prompt: string;
  userPrompt: string;
  turnId: string;
  eventCursorBefore: number;
  eventCursorAfter: number;
}

interface AcpTurnOutcome {
  action: ToolCall | null;
  reason?: string;
  requestError?: ErrorDiagnostic;
}

/**
 * 将 ACP Agent 适配为游戏 ActionProvider。
 *
 * Agent 的文本与 ACP update 仅用于可观测；只有注入的 werewolf-game MCP
 * server 的 submit_action tool 才会被返回给游戏引擎。
 */
export class AcpActionProvider implements ActionProvider {
  private readonly registry: AcpTurnRegistry;
  private readonly sessions = new AcpSessionPool((actorId) => {
    this.eventCursor.delete(actorId);
    this.sessionPromptByActor.delete(actorId);
  });
  private readonly fallbackProvider: ActionProvider;
  private readonly eventCursor = new Map<number, number>();
  private readonly sessionPromptByActor = new Map<number, string>();
  private readonly bugReportService: AgentBugReportService;
  private readonly promptPolicy: PlayerPromptPolicy;
  private readonly roundRecorder: PlayerRoundRecorder;
  private readonly pending = new Set<Promise<ToolCall | null>>();
  private readonly controllers = new Map<number, AbortController>();
  private readonly closeController = new AbortController();
  private closed = false;
  private readonly scheduler: ScopedRequestScheduler;
  private readonly observer: LlmObserver;

  constructor(
    world: World,
    private readonly options: AcpActionProviderOptions,
  ) {
    this.observer = new LlmObserver({
      transport: "acp",
      trace: options.trace ?? false,
      locale: options.displayLocale ?? world.locale,
      colorizeLogs: options.colorizeLogs,
      printLlmIo: options.printLlmIo ?? false,
      printThinking: options.printThinking ?? false,
    });
    this.scheduler = new ScopedRequestScheduler({
      defaultMaxConcurrentRequests: options.maxConcurrentRequests ?? Infinity,
      onWait: ({ request, queueDepth, active, limit }) =>
        this.observer.trace(
          `request_queue_wait player=${request.actorId} phase=${request.phase} queue_depth=${queueDepth} active=${active}/${limit}`,
        ),
    });
    const roleCatalog = options.roleCatalog ?? getDefaultRoleCatalog();
    this.bugReportService = new AgentBugReportService(world);
    this.registry = new AcpTurnRegistry(
      world,
      (report) => this.handleBugReport(report),
      roleCatalog,
    );
    const localization = getDefaultPhaseStageLocalizationRegistry();
    this.promptPolicy = new PlayerPromptPolicy(world, {
      personalityPromptResolver: options.personalityPromptResolver,
      toolSpecRegistry: getDefaultToolSpecRegistry(),
      roleCatalog,
      targetHintRegistry: getDefaultTargetHintRegistry(),
      phaseStageLocalizationRegistry: localization,
      configRenderRegistry: getDefaultConfigRenderRegistry(),
      boardConfig: options.boardConfig,
    });
    this.fallbackProvider =
      options.privilegedFallbackProvider ??
      new ObservationFallbackActionProvider(
        (request) => this.promptPolicy.buildObservation(request),
        options.fallbackStrategy ?? new ObservationFallbackStrategy(world.locale),
      );
    this.roundRecorder = new PlayerRoundRecorder(world);
  }

  get runtimeState() {
    return {
      closed: this.closed,
      turns: this.pending.size,
      registry: this.registry.snapshot,
      pool: this.sessions.snapshot,
      scheduler: this.scheduler.snapshot,
    };
  }

  getAction(request: ActionRequest): Promise<ToolCall | null> {
    if (this.closed) return Promise.reject(new Error("acp_provider_closed"));
    if (this.sessions.hasUnreclaimedResources)
      return Promise.reject(new Error("acp_resource_reclamation_failed"));
    if (this.controllers.has(request.actorId))
      return Promise.reject(new Error("acp_actor_turn_already_open"));
    const startedAt = Date.now();
    const bounded = {
      ...request,
      deadlineAtMs: Math.min(
        request.deadlineAtMs ?? Infinity,
        startedAt + (this.options.turnTimeoutMs ?? 45_000),
      ),
    };
    inheritRequestAlias(request, bounded);
    const controller = new AbortController();
    this.controllers.set(request.actorId, controller);
    const timer = setTimeout(
      () => controller.abort(new TurnDeadlineElapsed()),
      Math.max(0, bounded.deadlineAtMs - Date.now()),
    );
    let resolve!: (action: ToolCall | null) => void, reject!: (error: unknown) => void;
    const task = new Promise<ToolCall | null>((done, fail) => {
      resolve = done;
      reject = fail;
    });
    this.pending.add(task);
    void this.runScheduled(bounded, startedAt, controller.signal).then(resolve, reject);
    const cleanup = () => {
      clearTimeout(timer);
      this.controllers.delete(request.actorId);
      this.pending.delete(task);
    };
    return task.then(
      (action) => {
        cleanup();
        if (this.closed) return this.closedResult(request);
        if (
          bounded.context.action_failure_policy === "error" &&
          (controller.signal.aborted || bounded.deadlineAtMs <= Date.now())
        )
          throw new Error("action_turn_failed");
        return action;
      },
      (error) => {
        cleanup();
        throw error;
      },
    );
  }

  private async runScheduled(
    request: ActionRequest,
    startedAt: number,
    signal: AbortSignal,
  ): Promise<ToolCall | null> {
    let release: (() => void) | undefined;
    try {
      release = await this.scheduler.acquire(request, undefined, signal);
      this.observer.trace(
        `request_start player=${request.actorId} phase=${request.phase} tools=${request.allowedTools.join(",")} timeout_ms=${Math.max(0, request.deadlineAtMs! - Date.now())}`,
      );
      return await this.runTurn(request, startedAt, signal);
    } catch (error) {
      if (error === this.closeController.signal.reason) return this.closedResult(request);
      // 排队期限已耗尽后不新启模型／会话；原 runTurn 失败／回退分支仍在原时点处理该到期请求。
      if (!release && describeError(error).code === "request_timeout")
        return this.runTurn(request, startedAt, signal);
      throw error;
    } finally {
      // 未知或失败的回收不能变成新模型空位；关闭本 provider 等待者，只有显式新 runtime 才能重新装配。
      if (this.sessions.hasUnreclaimedResources)
        this.scheduler.close(new Error("acp_resource_reclamation_failed"));
      release?.();
    }
  }

  private async runTurn(
    request: ActionRequest,
    startedAt: number,
    signal: AbortSignal,
  ): Promise<ToolCall | null> {
    if (this.closed) return this.closedResult(request);
    const deadlineAtMs = request.deadlineAtMs!;
    let session: AcpSession | undefined;
    let turn: ReturnType<AcpTurnRegistry["openTurn"]> | undefined;
    let built: AcpTurnPromptBuild | undefined;
    let auditTrace: AcpSessionAuditTrace | undefined;
    let fallbackReason = "model_declined_required_action";
    let requestError: ErrorDiagnostic | undefined;
    let actionFailureReason: string | undefined;
    try {
      if (this.sessions.isClosed || deadlineAtMs <= Date.now())
        throw new Error("acp_deadline_elapsed");
      session = await awaitWithAbort(
        this.sessions.getOrCreate(request.actorId, deadlineAtMs, () => {
          const factory =
            this.options.sessionFactoryResolver?.(request.actorId) ?? this.options.sessionFactory;
          if (!factory) throw new Error("acp_session_factory_missing");
          const initialPrompt = this.buildSessionPrompt(request);
          this.observer.prompt([{ role: "system", content: initialPrompt }], request);
          if (this.closed) throw this.closeController.signal.reason;
          this.sessionPromptByActor.set(request.actorId, initialPrompt);
          return {
            factory,
            input: { actorId: request.actorId, registry: this.registry, initialPrompt },
          };
        }),
        signal,
      );
      if (this.sessions.isClosed || deadlineAtMs <= Date.now())
        throw new Error("acp_deadline_elapsed");
      turn = this.registry.openTurn(request, session.sessionId);
      built = this.buildTurnPrompt(request, turn.turnId, true);
      this.observer.prompt([{ role: "user", content: built.prompt }], request);
      if (this.closed) return this.closedResult(request);
      const promptTask = session.prompt(built.prompt);
      const outcome = await awaitWithAbort(
        this.waitForAction(turn.action, promptTask, request),
        signal,
      );
      if (this.closed) return this.closedResult(request);
      this.registry.closeTurn(turn.sessionId);
      if (outcome.reason === "request_timeout" || outcome.reason === "deadline_skip") {
        await this.sessions.discard(request.actorId);
      } else {
        let cancelled = true;
        try {
          await awaitBeforeDeadline(
            () => session!.cancel(),
            Math.min(deadlineAtMs, Date.now() + 300),
            signal,
          );
        } catch (error) {
          if (error === this.closeController.signal.reason) return this.closedResult(request);
          cancelled = false;
          // 有界取消超时触发强制回收；真实 RPC／adapter 失败仍归本 owner，最终 close 按原规则报告。
          if (!(error instanceof TurnDeadlineElapsed)) this.sessions.noteCleanupFailure(error);
        }
        if (
          !cancelled ||
          !(await settleWithin(promptTask, Math.min(1_000, Math.max(0, deadlineAtMs - Date.now()))))
        ) {
          await this.sessions.discard(request.actorId);
        }
      }
      if (this.closed) return this.closedResult(request);
      if (signal.aborted || deadlineAtMs <= Date.now())
        throw signal.reason ?? new Error("acp_deadline_elapsed");
      auditTrace = session.takeAuditTrace?.();
      if (this.closed) return this.closedResult(request);
      if (outcome.action) {
        this.observer.trace(
          `request_ok player=${request.actorId} phase=${request.phase} action=${outcome.action.name} args=${JSON.stringify(outcome.action.args)} elapsed_ms=${Date.now() - startedAt}`,
        );
        this.recordPlayerRound(request, built, {
          action: outcome.action,
          auditTrace,
          elapsedMs: Date.now() - startedAt,
        });
        this.rejectLateDelivery(request, built, startedAt);
        return this.closed ? this.closedResult(request) : outcome.action;
      }
      if (
        outcome.reason === "model_declined_required_action" &&
        resolveTurnConstraints(request).minValidActions === 0 &&
        (request.context.action_failure_policy !== "error" || turn.outcome.rejectedActions === 0)
      ) {
        this.observer.trace(
          `request_none player=${request.actorId} phase=${request.phase} elapsed_ms=${Date.now() - startedAt}`,
        );
        this.recordPlayerRound(request, built, {
          action: null,
          auditTrace,
          elapsedMs: Date.now() - startedAt,
        });
        this.rejectLateDelivery(request, built, startedAt);
        return null;
      }
      if (request.context.action_failure_policy === "error" && turn.outcome.rejectedActions) {
        fallbackReason = turn.outcome.failureCode ?? "action_turn_failed";
        actionFailureReason = fallbackReason;
      } else fallbackReason = outcome.reason ?? fallbackReason;
      requestError = outcome.requestError ?? requestError;
    } catch (error) {
      await this.sessions.discard(request.actorId);
      if (error === this.closeController.signal.reason) return this.closedResult(request);
      fallbackReason = "runtime_error";
      requestError = describeError(error);
      this.observer.trace(
        `request_transport_fail player=${request.actorId} phase=${request.phase} err=${formatErrorDiagnostic(error, this.observer.locale)}`,
      );
      if (this.closed) return this.closedResult(request);
      safeRecordLogicOp({
        scope: "llm_action_provider",
        op: "action_provider_error",
        actorId: request.actorId,
        phase: request.phase,
        status: "fallback",
        reason: requestError.code,
        output: { diagnostic: requestError },
      });
    } finally {
      if (turn) {
        this.registry.closeTurn(turn.sessionId);
      }
    }
    if (this.closed) return this.closedResult(request);
    built ??= this.buildTurnPrompt(request, turn?.turnId ?? "unopened", false);
    auditTrace ??= session?.takeAuditTrace?.();
    if (this.closed) return this.closedResult(request);
    let fallback: ToolCall | null;
    try {
      fallback = allowsActionFallback(request)
        ? await awaitBeforeDeadline(
            () => this.fallbackProvider.getAction(request),
            deadlineAtMs,
            this.closeController.signal,
          )
        : null;
    } catch (error) {
      if (error === this.closeController.signal.reason) return this.closedResult(request);
      if (!(error instanceof TurnDeadlineElapsed)) throw error;
      fallback = null;
      fallbackReason = "deadline_skip";
    }
    if (this.closed) return this.closedResult(request);
    this.observer.trace(
      `request_recovered player=${request.actorId} phase=${request.phase} reason=${fallbackReason} fallback=${fallback?.name ?? "none"}`,
    );
    this.recordPlayerRound(request, built, {
      action: fallback,
      auditTrace,
      elapsedMs: Date.now() - startedAt,
      fallbackReason,
      requestError,
      actionFailureReason,
    });
    if (!this.closed && request.context.action_failure_policy === "error" && !fallback)
      throw new Error("action_turn_failed");
    return this.closed ? this.closedResult(request) : fallback;
  }

  async close(): Promise<void> {
    this.closed = true;
    this.closeController.abort(new DOMException("acp_provider_closed", "AbortError"));
    this.scheduler.close(this.closeController.signal.reason);
    this.registry.close();
    for (const controller of this.controllers.values())
      controller.abort(this.closeController.signal.reason);
    const failures: unknown[] = [];
    const closing = this.sessions.close().catch((error) => {
      failures.push(error);
    });
    const settled = await Promise.allSettled([...this.pending]);
    for (const result of settled)
      if (result.status === "rejected" && result.reason !== this.closeController.signal.reason)
        failures.push(result.reason);
    await closing;
    this.eventCursor.clear();
    this.sessionPromptByActor.clear();
    if (failures.length) throw new AggregateError(failures, "acp_provider_close_failed");
  }

  private async waitForAction(
    action: Promise<ToolCall | null>,
    promptTask: Promise<void>,
    request: ActionRequest,
  ): Promise<AcpTurnOutcome> {
    const timeoutMs = this.resolveTimeoutMs(request);
    if (timeoutMs <= 0) {
      return { action: null, reason: "deadline_skip" };
    }
    let timer: NodeJS.Timeout | undefined;
    try {
      return await Promise.race([
        action.then((value) => ({ action: value })),
        // 原竞速在 Agent 回合完成而未提交时进入回退，不继续等待整段 LLM 超时；
        // action／prompt 的原 Promise 顺序和拒绝原因保持，不把完成文本当领域提交。
        promptTask.then(
          (): AcpTurnOutcome => ({ action: null, reason: "model_declined_required_action" }),
          (error): AcpTurnOutcome => ({
            action: null,
            reason: "runtime_error",
            requestError: describeError(error),
          }),
        ),
        new Promise<AcpTurnOutcome>((resolve) => {
          timer = setTimeout(() => resolve({ action: null, reason: "request_timeout" }), timeoutMs);
        }),
      ]);
    } finally {
      if (timer) clearTimeout(timer);
    }
  }

  private resolveTimeoutMs(request: ActionRequest): number {
    const configured = this.options.turnTimeoutMs ?? 45_000;
    const remaining =
      request.deadlineAtMs === undefined
        ? configured
        : Math.max(0, request.deadlineAtMs - Date.now());
    return Math.min(configured, remaining);
  }
  private closedResult(request: ActionRequest): null {
    if (request.context.action_failure_policy === "error") throw this.closeController.signal.reason;
    return null;
  }
  private rejectLateDelivery(
    request: ActionRequest,
    built: AcpTurnPromptBuild,
    startedAt: number,
  ): void {
    if (
      request.context.action_failure_policy !== "error" ||
      (request.deadlineAtMs ?? Infinity) > Date.now()
    )
      return;
    this.recordPlayerRound(request, built, {
      action: null,
      elapsedMs: Date.now() - startedAt,
      requestError: { code: "request_timeout" },
    });
    throw new Error("action_turn_failed");
  }

  /** 创建 session 时复用 LLM provider 的既有身份、规则和板子系统提示。 */
  private buildSessionPrompt(request: ActionRequest): string {
    return this.promptPolicy.buildSystem(request, {
      supportsDebugReporting: true,
      includeToolUseInstructions: false,
    }).systemPrompt;
  }

  /** 回合提示遵循既有阶段规则、目标提示与可见事件增量结构。 */
  private buildTurnPrompt(
    request: ActionRequest,
    turnId: string,
    advanceCursor: boolean,
  ): AcpTurnPromptBuild {
    const lines: string[] = [];
    const events = parsePlayerVisibleEvents(request.context.visible_events);
    const cursor = this.eventCursor.get(request.actorId) ?? 0;
    const delta = events.filter((event) => event.seq > cursor);
    const nextCursor = events.reduce((maxSeq, event) => Math.max(maxSeq, event.seq), cursor);
    if (advanceCursor) this.eventCursor.set(request.actorId, nextCursor);
    if (delta.length) {
      lines.push(
        text(this.promptPolicy.locale, "prompt.acp.events", {
          events: encodePlayerVisibleEventBatch(delta),
        }),
      );
    }
    lines.push(text(this.promptPolicy.locale, "prompt.acp.turn", { turn: turnId }));
    const userPrompt = this.promptPolicy.buildUser(request, {
      turnId,
      allowedTools: request.allowedTools,
      actionSubmissionHint: text(this.promptPolicy.locale, "prompt.acp.submit", { turn: turnId }),
    });
    lines.push(userPrompt);
    return {
      prompt: lines.filter(Boolean).join("\n"),
      userPrompt,
      turnId,
      eventCursorBefore: cursor,
      eventCursorAfter: advanceCursor ? nextCursor : cursor,
    };
  }

  /** 将 ACP 回合映射到与直接 LLM 路径相同的玩家审计结构。 */
  private recordPlayerRound(
    request: ActionRequest,
    built: AcpTurnPromptBuild,
    input: {
      action: ToolCall | null;
      auditTrace?: AcpSessionAuditTrace;
      elapsedMs: number;
      fallbackReason?: string;
      requestError?: ErrorDiagnostic;
      actionFailureReason?: string;
    },
  ): void {
    if (this.closed) return;
    const systemPrompt =
      this.sessionPromptByActor.get(request.actorId) ?? this.buildSessionPrompt(request);
    if (this.closed) return;
    const thinkingText = this.formatAuditTrace(input.auditTrace);
    const actionArgs = input.action
      ? ((input.action.args ?? {}) as Record<string, unknown>)
      : undefined;
    const prompt: BuiltPlayerPrompt = {
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: built.userPrompt },
      ],
      systemPrompt,
      userPrompt: built.userPrompt,
      boardInfoPrompt: this.promptPolicy.buildBoardInfo(),
      isInitialRound: false,
      eventCursorBefore: built.eventCursorBefore,
      eventCursorAfter: built.eventCursorAfter,
      contextWindowStart: 0,
      contextWindowEnd: 0,
      contextWindowTotal: 0,
      turnId: built.turnId,
      auditMetadata: [
        `transport=acp_mcp;turn_id=${built.turnId};event_cursor=${built.eventCursorBefore}->${built.eventCursorAfter};elapsed_ms=${input.elapsedMs}`,
      ],
    };
    const outcome: PlayerRoundOutcome = {
      ...(thinkingText ? { thinkingText } : {}),
      actionMode: input.action ? "tool_call" : "none",
      toolCalls: input.action
        ? [
            {
              name: input.action.name,
              args: actionArgs ?? {},
              accepted: true,
              result: {
                transport: "acp_mcp",
                turn_id: built.turnId,
              },
            },
          ]
        : [],
      finalAction: input.action,
      ...(input.requestError
        ? {
            retryTrace: [
              {
                attempt: 0,
                status: "request_error",
                reason: input.requestError.code,
                diagnostic: input.requestError,
              },
            ],
          }
        : input.actionFailureReason
          ? {
              retryTrace: [
                { attempt: 0, status: "no_valid_action", reason: input.actionFailureReason },
              ],
            }
          : {}),
      ...(input.fallbackReason
        ? {
            fallback: {
              used: allowsActionFallback(request),
              reason: input.fallbackReason,
              ...(input.action
                ? { action: { name: input.action.name, args: actionArgs ?? {} } }
                : {}),
            },
          }
        : {}),
    };
    if (!this.closed) this.roundRecorder.record(request, prompt, outcome);
  }

  private formatAuditTrace(trace?: AcpSessionAuditTrace): string | undefined {
    if (!trace) return undefined;
    const thoughts = trace.thoughts.join(" ").trim().slice(0, 2_000);
    const messages = trace.messages.join(" ").trim().slice(0, 2_000);
    const lines = [
      ...(thoughts ? [`thought: ${thoughts}`] : []),
      ...(messages ? [`message: ${messages}`] : []),
    ];
    return lines.length ? lines.join("\n") : undefined;
  }

  /** ACP report_bug 与直接 LLM 路径共享落盘语义及限流规则。 */
  private handleBugReport(report: AcpBugReport): McpBridgeResult {
    const result = this.bugReportService.report(report);
    if (result.ok && result.accepted) {
      this.options.onBugReport?.(report);
      return { ok: true, accepted: true };
    }
    return result;
  }
}
